// Independent limited intake: no Go compilation, remote calls or request mutation.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import {validateGoEvents} from './d-resources-mysql-actual-review-20261023.mjs';
const root=path.resolve(import.meta.dirname,'../..');
const local=p=>{const f=path.resolve(root,p);assert.ok(f.startsWith(root+path.sep));return f;};
const bytes=p=>fs.readFileSync(local(p));
const json=p=>JSON.parse(bytes(p).toString('utf8').replace(/^\uFEFF/,''));
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const pin=p=>({path:path.relative(root,local(p)).replaceAll('\\','/'),size:bytes(p).length,sha256:sha(bytes(p))});
const requestPath='docs/evidence/d-gc-full-profile-preparation-request-20261026.json';
const request=json(requestPath),source=json(request.compile_source_manifest),receipt=json(request.receipt);
assert.equal(request.kind,'d_gc_full_profile_preparation_review_request.v1');
assert.equal(source.kind,'d_gc_full_frozen_source.v1');
assert.deepEqual(Object.keys(source).sort(),['dependencies_installed','files','kind','source_sha256','stable_copy_verified']);
assert.equal(source.stable_copy_verified,true);assert.equal(source.dependencies_installed,false);
assert.equal(source.files.length,1659);
assert.deepEqual(source.files.map(p=>p.path),[...new Set(source.files.map(p=>p.path))].sort());
for(const p of source.files){assert.deepEqual(Object.keys(p).sort(),['path','sha256','size']);assert.match(p.path,/^(backend|contracts|scripts|docs)\//);assert.ok(!p.path.includes('\\')&&!p.path.split('/').some(s=>['.','..',''].includes(s)));assert.ok(Number.isSafeInteger(p.size)&&p.size>=0);assert.match(p.sha256,/^[a-f0-9]{64}$/);}
assert.equal(sha(Buffer.from(source.files.map(p=>`${p.path}\0${p.sha256}\0${p.size}`).join('\n')+'\n')),source.source_sha256);
assert.equal(source.source_sha256,'3bdf32b2014892f68fc932bdbcc40e4ba0ebd7fd74c01eca4765c8127b1355dc');
assert.equal(source.source_sha256,request.compile_source_sha256);
assert.equal(receipt.kind,'d_gc_full_profile_local_preparation.v1');assert.equal(receipt.error,null);
assert.equal(local(receipt.source_manifest),local(request.compile_source_manifest));
assert.equal(receipt.seed_exit,0);assert.equal(receipt.linux_compile_exit,0);assert.equal(receipt.frozen_source_postcheck,true);
assert.equal(receipt.linux_binary_sha256,'70c0bddc2bb3b8e001b73e2ff585feb57a48d77d945389ca2979bdb3d5c1af29');
assert.equal(receipt.binary_removed,true);assert.equal(receipt.owner_removed,true);
assert.equal(path.dirname(receipt.owner),root);assert.match(path.basename(receipt.owner),/^\.tmp-d-index-cache-[a-f0-9]{32}$/);assert.equal(fs.existsSync(receipt.owner),false);
for(const name of ['actual_mysql','public_collect','complete_group_fixture','production_approved','whole_tree_ready','dependencies_installed'])assert.equal(receipt[name],false);
const tests=validateGoEvents(bytes(receipt.seed_log).toString('utf8'),'clawreef/internal/systembackupevidence');
assert.deepEqual(tests,['TestDDownloadGCFullProfileMySQLSeed']);
const prefix=request.receipt.slice(0,-5);assert.equal(bytes(prefix+'-linux.txt').length,0);
assert.deepEqual(pin(request.tagged_probe.path),request.tagged_probe);
assert.deepEqual(source.files.find(p=>p.path===request.tagged_probe.path),request.tagged_probe);
for(const p of request.current_scripts)assert.deepEqual(pin(p.path),{path:p.path,size:p.size,sha256:p.sha256});
const original=json('docs/evidence/d-gc-full-review-request-20261026.json');
assert.equal(original.source_sha256,'093f6b84d87d70bafc2819b351d1d36874dea32cd35e89420461f218e8eb8def');
for(const p of original.owned_inputs)assert.deepEqual(pin(p.path),p,'original GC input changed');
const probe=bytes(request.tagged_probe.path).toString('utf8');
for(const literal of ['func TestDDownloadGCFullProfileMySQLSeed(', 'func TestDDownloadGCFullProfileMySQL(', 'return nil, ErrDenied', 'FULL_PROFILE_WAIT case=', 'out.Transaction != "committed"', 'out.Unlock != "confirmed"', 'if (n == 0) != commit', 'public_collect=no full_group=no'])assert.ok(probe.includes(literal),literal);
const phase=bytes('scripts/system-backup-d-download-gc-full-profile-phase.sh').toString('utf8');
for(const literal of ['-test.list "^TestDDownloadGCFullProfileMySQL$"','-eq 31','--- SKIP:','public_collect=no','full_group=no','full_gc=not_run','production_approval=no'])assert.ok(phase.includes(literal),literal);
const runner=bytes('scripts/system-backup-d-gc-full-profile-prepare.ps1').toString('utf8');
for(const literal of ["$env:GOPROXY='off'","$env:GOSUMDB='off'","$env:GOTOOLCHAIN='local'",'-mod=readonly','-count=1'])assert.ok(runner.includes(literal));
assert.ok(!runner.includes('-vet=off'));
const paths=[requestPath,request.compile_source_manifest,request.receipt,receipt.seed_log,prefix+'-linux.txt','docs/evidence/a-gc-full-profile-preparation-review-20261026.mjs','docs/evidence/d-gc-full-review-request-20261026.json',request.tagged_probe.path,...request.current_scripts.map(p=>p.path)];
const report={kind:'a_gc_full_profile_preparation_limited_review.v1',status:'accepted_exact_local_seed_compile_and_dispatch_preparation_only',source_sha256:source.source_sha256,source_files:1659,native_seed_roots:1,native_seed_pass_events:1,planned_profile_cases:31,actual_profile_cases_accepted:0,linux_compile_exit:0,binary_hash_reported_in_terminal_receipt:receipt.linux_binary_sha256,deleted_binary_independently_rehashed:false,frozen_source_postcheck:true,owner_independently_absent:receipt.owner,original_093f_GC_inputs_unchanged:true,dispatch_replay_observation:{full_profile_exit:0,historical_freeze_dispatch_exit:0,source:'A1 exec tool returns efa05f and 0e34e4; dispatch only, no Go or remote'},public_collect_actual_ready:false,complete_group_fixture_ready:false,whole_current_worktree_approved:false,real_protocol_authority_approved:false,actual_mysql:false,dependencies_installed:false,production_approved:false,goal_complete:false,remaining_local_work:request.remaining_local_work,inputs:[...new Set(paths)].sort().map(pin)};
